<?php
require __DIR__.'/app/bootstrap.php';
require __DIR__.'/app/schema.php';
$error='';$complete=false;
try { $pdo=db(); if((int)$pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='admins'")->fetchColumn()>0 && (int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0){$complete=true;} }
catch(Throwable $ex){$error='Database connection failed. Check the database name, username, password and host in config.php. The database itself must already exist in your hosting control panel.';}
if(!$error && !$complete && $_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$name=trim((string)($_POST['name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');
 if($name===''||!$email||strlen($password)<12){$error='Enter your name, a valid email, and a password with at least 12 characters.';}
 else{try{install_schema($pdo);$stmt=$pdo->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$complete=true;}catch(Throwable $ex){$error='Setup could not finish. Check that the database user can create tables and insert records.';}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fitzeno Setup</title><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;700;800&family=DM+Sans:wght@400;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?=e(url('assets/css/site.css'))?>"></head><body class="setup-body"><main class="setup-card"><a class="wordmark" href="<?=e(url())?>">FITZENO<span>®</span></a><?php if($complete):?><span class="eyebrow">YOUR CLUB IS READY</span><h1>GOOD TO<br>GO.</h1><p>Fitzeno is installed. Sign in to your private admin panel and start making the site your own.</p><a class="button button-dark" href="<?=e(url('control-room/login'))?>">OPEN ADMIN ↗</a><p class="setup-note">For security, remove install.php from your hosting account after setup.</p><?php else:?><span class="eyebrow">FITZENO · FIRST-RUN SETUP</span><h1>MAKE IT<br>YOUR CLUB.</h1><p>Create the first administrator. The starter catalogue includes 30 products, six journal articles and six class types.</p><?php if($error):?><div class="admin-alert"><?=e($error)?></div><?php endif;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Your name<input name="name" required autocomplete="name"></label><label>Admin email<input name="email" type="email" required autocomplete="email"></label><label>Password <small>(12 characters minimum)</small><input name="password" type="password" required minlength="12" autocomplete="new-password"></label><button class="button button-dark" type="submit">INSTALL FITZENO ↗</button></form><p class="setup-note">Before this step, update database credentials in config.php and create an empty MySQL database from your hosting control panel.</p><?php endif;?></main></body></html>
